import {characters,questions,matches,labels} from './data.js';
import {allIds,narrow,chooseComputerMove,createReferee} from './engine.js';
const $=s=>document.querySelector(s), app=$('#app'), dialog=$('#dialog');
const palette={red:'#e64050',blue:'#297dc1',green:'#4d9d63',black:'#555368',purple:'#8854b2',yellow:'#d9a41e',white:'#659aab',orange:'#d87b31',silver:'#7b8d9e',brown:'#927044'};
let game=null, setup=null, screen='home',selected=null, sound=false, selectionMode='flip', revealed=false;
let stats={wins:0,losses:0,p1:0,p2:0},audio;
try{stats={...stats,...JSON.parse(localStorage.getItem('mmw-scores')||'{}')};sound=localStorage.getItem('mmw-sound')==='true'}catch{}
function save(){try{localStorage.setItem('mmw-scores',JSON.stringify(stats));localStorage.setItem('mmw-sound',String(sound))}catch{}}
function beep(high=false){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=high?660:260;g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.start();o.stop(audio.currentTime+.13)}catch{}}
function soundLabel(){$('#sound').textContent=sound?'Sound on':'Sound off';$('#sound').setAttribute('aria-pressed',String(sound))}
function card(c,{out=false,pick=false,staticCard=false}={}){
 const mono=c.name.split(/[ -]/).map(x=>x[0]).slice(0,2).join('');
 return '<'+(staticCard?'div':'button')+' class="card'+(out?' out':'')+(pick?' selected':'')+'" '+(staticCard?'':'data-card="'+c.id+'" aria-label="'+c.name+(out?', eliminated':'')+'" aria-pressed="'+pick+'"')+'><span class="portrait" style="--c:'+palette[c.color]+'"><span class="issue">#'+String(c.id+1).padStart(2,'0')+'</span><span class="monogram">'+mono+'</span><span class="role">'+c.alignment.toUpperCase()+'</span></span><span class="card-name">'+c.name+'</span></'+(staticCard?'div':'button')+'>';
}
function scorebar(){return '<div class="stats"><span><b>'+stats.wins+'</b> CPU WINS</span><span><b>'+stats.losses+'</b> CPU LOSSES</span><span><b>'+stats.p1+' : '+stats.p2+'</b> PLAYER 1 / PLAYER 2</span></div>'}
function home(){screen='home';game=null;setup=null;$('#restart').disabled=true;app.innerHTML='<section class="hero"><div><p class="eyebrow">THE COMIC-BOOK DEDUCTION GAME</p><span class="tag">48 SUSPECTS. ONE SECRET IDENTITY.</span><h1>EVERY HERO<br>HAS A <em>SECRET.</em></h1><p class="lead">Hero or villain? Tech or magic? Ask the right questions. Flip the suspects. Unmask your opponent before they find you.</p><div class="mode-grid"><button class="mode primary" data-action="cpu"><strong>Play vs Computer →</strong><small>Outsmart the machine.<br>Three difficulty levels.</small></button><button class="mode" data-action="local"><strong>Two Players →</strong><small>One device. Two detectives.<br>Private pass-and-play.</small></button></div><p class="hint">No account. No downloads. Just one more round.</p></div><div class="preview-cards" aria-label="Six of the 48 character cards">'+[0,35,16,7,36,9].map(id=>card(characters[id],{staticCard:true})).join('')+'<div class="burst">WHO’S HIDING ON THE OTHER SIDE?</div></div></section>'+scorebar()+'<section><div class="section-head"><h2>Meet the suspects</h2><small>Tap a card to see its game traits</small></div><div class="board">'+characters.map(c=>card(c)).join('')+'</div></section>'}
function modal(title,body){if(dialog.open)dialog.close();$('#dialog-content').innerHTML='<h2 id="dialog-title">'+title+'</h2>'+body;dialog.showModal()}
function close(){dialog.close();$('#dialog-content').innerHTML=''}
function traits(c){return '<dl>'+Object.entries(labels).map(([k,l])=>'<dt>'+l+'</dt><dd>'+c[k]+'</dd>').join('')+'</dl>'}
function detail(id){const c=characters[id];modal(c.name,traits(c)+'<p class="hint">Answers use these fixed game traits. Comic versions and allegiances can differ.</p><div class="actions"><button data-action="close">Back</button></div>')}
function start(mode,difficulty='medium'){close();game=null;setup={mode,difficulty,secrets:[]};selected=null;$('#restart').disabled=true;if(mode==='local')privacy(0,'select');else selectSecret(0)}
function privacy(player,phase){screen='privacy';revealed=false;selected=null;app.innerHTML='<section class="privacy"><div class="lock" aria-hidden="true">✦</div><p class="eyebrow">PRIVATE PASS-AND-PLAY</p><h1>OVER TO<br>PLAYER '+(player+1)+'.</h1><p>Pass the device. Only Player '+(player+1)+' should look at the next screen.</p><span class="badge">THE BOARD, SECRET & LOG ARE HIDDEN</span><button class="primary" data-action="ready" data-player="'+player+'" data-phase="'+phase+'">I’m Player '+(player+1)+' — ready</button></section>';window.scrollTo(0,0)}
function selectSecret(player){screen='select';selected=null;app.innerHTML='<section class="selection"><p class="eyebrow">'+(setup.mode==='cpu'?'YOU VS COMPUTER · '+setup.difficulty.toUpperCase():'PLAYER '+(player+1)+' · PRIVATE SELECTION')+'</p><div class="section-head"><h1>Choose your secret identity.</h1></div><p class="hint">Your opponent must find this character. Tap a card, then lock it in. Each card’s traits define all answers.</p><div class="board">'+characters.map(c=>card(c)).join('')+'</div><div class="selection-actions"><span id="choice">No character selected</span><button class="primary" data-action="lock" data-player="'+player+'" disabled>Lock in secret →</button></div></section>';window.scrollTo(0,0)}
function lockSecret(player){if(selected===null)return;setup.secrets[player]=selected;if(setup.mode==='local'&&player===0){privacy(1,'select');return}if(setup.mode==='cpu')setup.secrets[1]=Math.floor(Math.random()*characters.length);const {mode,difficulty,secrets}=setup;
 game={mode,difficulty,ref:createReferee(...secrets),turn:0,boards:[allIds(),allIds()],used:[[],[]],manual:[new Set(),new Set()],logs:[[],[]],ended:false,round:1};setup=null;selectionMode='flip';revealed=false;
 $('#restart').disabled=false;if(mode==='local')privacy(0,'play');else renderGame()}
function activeCandidates(){return game.boards[game.turn].filter(id=>!game.manual[game.turn].has(id))}
function renderGame(){screen='game';selected=null;const p=game.turn,candidates=activeCandidates(),available=questions.filter(q=>!game.used[p].includes(q.id));const options=Object.entries(labels).map(([k,l])=>'<optgroup label="'+l+'">'+available.filter(q=>q.key===k).map(q=>'<option value="'+q.id+'">'+q.text+'</option>').join('')+'</optgroup>').join('');
 app.innerHTML='<div class="game-head"><div><p class="eyebrow">'+(game.mode==='cpu'?'COMPUTER · '+game.difficulty.toUpperCase():'LOCAL TWO-PLAYER')+' · TURN '+game.round+'</p><h1>'+(game.mode==='cpu'?'Your turn. Make it count.':'Player '+(p+1)+', you’re up.')+'</h1><p>Find '+(game.mode==='cpu'?'the computer':'Player '+(2-p))+'’s secret identity.</p></div><span class="count">'+candidates.length+' / 48 LEFT</span></div><div class="layout"><section class="board-wrap"><div class="section-head"><h2>Suspect board</h2><button class="quiet" data-action="toggle-mode">'+(selectionMode==='flip'?'Card tap: flip':'Card tap: inspect')+'</button></div><div class="board">'+characters.map(c=>card(c,{out:!candidates.includes(c.id)})).join('')+'</div><p class="hint">Tap cards to eliminate or restore manually. Questions filter automatically. Use “Card tap: inspect” to read a card’s exact traits.</p><button class="quiet" data-action="restore">Clear manual flips</button></section><aside><section class="panel ask-panel"><h2>01 / Follow the clues</h2><label class="sr-only" for="question">Choose a question</label><select id="question">'+options+'</select><button class="primary" data-action="ask" '+(!available.length?'disabled':'')+'>Ask question →</button><button class="quiet" data-action="guess">Make final guess</button><p class="hint">One question or guess per turn. A wrong final guess loses.</p></section><section class="panel secret-panel"><h2>Your secret identity</h2><div class="secret-info" id="secret-info">'+(revealed?'<strong>'+game.ref.own(p).name+'</strong>'+traits(game.ref.own(p)):'Identity concealed. Reveal only when your opponent is looking away.')+'</div><button class="quiet" data-action="reveal">'+(revealed?'Hide secret':'Reveal my secret')+'</button></section><section class="panel log-panel"><details><summary>Your question log ('+game.logs[p].length+')</summary><div class="log">'+(game.logs[p].map(x=>'<p>'+x+'</p>').join('')||'<p>No clues yet. Start asking.</p>')+'</div></details></section></aside></div>';
}
function ask(){if(screen!=='game'||game.ended)return;const p=game.turn,q=questions.find(q=>q.id===$('#question').value);if(!q||game.used[p].includes(q.id))return;const answer=game.ref.answer(1-p,q);game.used[p].push(q.id);game.boards[p]=narrow(game.boards[p],q,answer);game.logs[p].unshift(q.text+' <b>'+(answer?'YES':'NO')+'</b>');revealed=false;beep(answer);renderGame();modal(answer?'YES!':'NO!', '<p>'+q.text+'</p><p>Your board now has <b>'+activeCandidates().length+' suspect'+(activeCandidates().length===1?'':'s')+'</b>.</p><div class="actions"><button data-action="next">'+(game.mode==='cpu'?'Computer’s turn →':'Hide & pass device →')+'</button></div>')}
function next(){close();if(game.mode==='local'){game.turn=1-game.turn;game.round++;privacy(game.turn,'play');return}computerTurn()}
function computerTurn(){const view={candidates:[...game.boards[1]],used:[...game.used[1]]};const move=chooseComputerMove(view,game.difficulty);if(move.type==='guess'){end(game.ref.guess(0,move.id)?1:0,'The computer guessed '+characters[move.id].name+'.');return}
 const q=move.question,answer=game.ref.answer(0,q);game.used[1].push(q.id);game.boards[1]=narrow(game.boards[1],q,answer);game.round++;renderGame();modal('The computer asks…','<p>'+q.text+'</p><p>The referee answers <b>'+(answer?'YES':'NO')+'</b> using your secret’s game traits.</p><p>Computer suspects remaining: <b>'+game.boards[1].length+'</b></p><div class="actions"><button data-action="close">Your turn →</button></div>')}
function guess(){const ids=activeCandidates();modal('Ready to unmask them?','<p>A wrong final guess loses the game.</p>'+(!ids.length?'<p>No suspects remain. Clear manual flips to restore eligible characters.</p>':'<label for="guess-select">Choose your final guess</label><select id="guess-select">'+ids.map(id=>'<option value="'+id+'">'+characters[id].name+'</option>').join('')+'</select>')+'<div class="actions">'+(ids.length?'<button class="primary" data-action="confirm-guess">Lock in guess</button>':'')+'<button class="quiet" data-action="close">Keep investigating</button></div>')}
function end(winner,reason){close();game.ended=true;revealed=false;screen='result';const secrets=game.ref.reveal();if(game.mode==='cpu')stats[winner===0?'wins':'losses']++;else stats[winner===0?'p1':'p2']++;save();beep(true);
 app.innerHTML='<section class="privacy result"><span class="tag">CASE CLOSED</span><h1>'+(game.mode==='cpu'?(winner===0?'YOU CRACKED IT!':'COMPUTER WINS!'):'PLAYER '+(winner+1)+' WINS!')+'</h1><p>'+reason+'</p><div class="panel"><p><b>'+(game.mode==='cpu'?'Your secret':'Player 1')+':</b> '+secrets[0].name+'<br><b>'+(game.mode==='cpu'?'Computer secret':'Player 2')+':</b> '+secrets[1].name+'</p></div><button class="primary" data-action="again">Play again →</button><button class="quiet" data-action="home">Choose game mode</button></section>'+scorebar();window.scrollTo(0,0)}
function rules(){modal('How to play','<ol><li>Choose a secret character privately. The computer chooses its own.</li><li>Ask one yes/no question per turn. The referee answers from fixed character traits and flips every nonmatching card.</li><li>Your opponent gets a turn after each question. In local play, read the answer, then hide the screen and pass the device.</li><li>Make a final guess when ready. A correct guess wins. A wrong guess loses immediately.</li></ol><p><b>Trait rule:</b> This roster uses one fixed version of each character. Inspect cards for color, affiliation, powers, and other answers. The listed traits take priority over other comic or movie versions.</p><p><b>Difficulty:</b> Easy asks a random useful question. Medium chooses among four strong splits. Hard always chooses the most balanced split. Every difficulty guesses once only one suspect remains.</p><p>Scores are saved on this browser. Sound is optional. Local privacy protects normal pass-and-play; it is not protection against someone inspecting browser memory.</p><div class="actions"><button data-action="close">Got it</button></div>')}
document.addEventListener('click',event=>{
 const cardButton=event.target.closest('[data-card]');if(cardButton){const id=Number(cardButton.dataset.card);beep();if(screen==='select'){selected=id;app.querySelectorAll('[data-card]').forEach(el=>{const yes=Number(el.dataset.card)===id;el.classList.toggle('selected',yes);el.setAttribute('aria-pressed',String(yes))});$('#choice').textContent=characters[id].name;app.querySelector('[data-action="lock"]').disabled=false}
 else if(screen==='game'){if(selectionMode==='inspect'){detail(id);return}const p=game.turn;if(!game.boards[p].includes(id)){modal('Filtered by a clue','<p>This card does not match a previous answer and cannot be restored. Manual flips can be cleared separately.</p><div class="actions"><button data-action="close">Back</button></div>');return}game.manual[p].has(id)?game.manual[p].delete(id):game.manual[p].add(id);renderGame()}else if(screen==='home')detail(id);return}
 const button=event.target.closest('button');if(!button||button.disabled)return;const action=button.dataset.action;
 if(action==='close'){close();return}
 if(action==='cpu')modal('Choose your challenge','<p>All opponents play fairly. Pick how efficiently the computer searches.</p><label for="difficulty">Computer difficulty</label><select id="difficulty"><option value="easy">Easy — random useful questions</option><option value="medium" selected>Medium — strong questions</option><option value="hard">Hard — best possible split</option></select><div class="actions"><button class="primary" data-action="start-cpu">Choose my secret →</button><button class="quiet" data-action="close">Back</button></div>');
 if(action==='start-cpu')start('cpu',$('#difficulty').value);
 if(action==='local')start('local');
 if(action==='ready')button.dataset.phase==='select'?selectSecret(Number(button.dataset.player)):renderGame();
 if(action==='lock')lockSecret(Number(button.dataset.player));
 if(action==='ask')ask();
 if(action==='next')next();
 if(action==='reveal'){revealed=!revealed;renderGame()}
 if(action==='toggle-mode'){selectionMode=selectionMode==='flip'?'inspect':'flip';renderGame()}
 if(action==='restore'){game.manual[game.turn].clear();renderGame()}
 if(action==='guess')guess();
 if(action==='confirm-guess'){const id=Number($('#guess-select').value),p=game.turn;end(game.ref.guess(1-p,id)?p:1-p,(game.mode==='cpu'?'You':'Player '+(p+1))+' guessed '+characters[id].name+'.')}
 if(action==='again')start(game.mode,game.difficulty);
 if(action==='home'){close();home()}
 if(action==='restart-confirm')start(game.mode,game.difficulty);
 if(button.id==='rules')rules();
 if(button.id==='new'){if(game&&!game.ended)modal('Start a new case?','<p>This clears the current game. Your saved scores stay.</p><div class="actions"><button class="primary" data-action="home">New game</button><button class="quiet" data-action="close">Keep playing</button></div>');else{close();home()}}
 if(button.id==='restart'&&game)modal('Restart this match?','<p>Reset boards, clues and turns. You’ll choose fresh secret characters.</p><div class="actions"><button class="primary" data-action="restart-confirm">Restart match</button><button class="quiet" data-action="close">Cancel</button></div>');
 if(button.id==='sound'){sound=!sound;save();soundLabel();beep(true)}
});
// Escape cannot skip a required answer acknowledgement / handoff.
dialog.addEventListener('cancel',event=>{event.preventDefault();if(!$('#dialog-content [data-action="next"]'))close()});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&screen==='game'&&revealed){revealed=false;renderGame()}});
soundLabel();home();
